var stepState = 'start';
var currentCase = 'left';
var demoIndex = -1;
var stackStates = ['start', 'testCandidate', 'leftTurnPush', 'nonleftTurnPop', 'done'];

var demoSteps = [
  {
    title: 'Candidate outside the current hull',
    narration: 'In the left-turn case, pᵢ lies outside the current polygon Qⱼ. Adding pᵢ replaces edge p₀-pⱼ with p₀-pᵢ and pᵢ-pⱼ, so the hull grows.',
    state: { turnCase: 'Left turn: point joins hull', stackUpdate: 'leftTurnPush' }
  },
  {
    title: 'Candidate hidden inside a triangle',
    narration: 'In the nonleft-turn case, pₜ is inside triangle pᵢpᵣp₀. Since that surrounding triangle already contains it, pₜ cannot be an extreme point.',
    state: { turnCase: 'Nonleft turn: point is interior', stackUpdate: 'testCandidate' }
  },
  {
    title: "Why Graham's scan pops points",
    narration: 'When the angle test gives a nonleft turn, the middle point on the stack is not part of the final hull. The algorithm removes it and tests again.',
    state: { turnCase: 'Nonleft turn: point is interior', stackUpdate: 'nonleftTurnPop' }
  },
  {
    title: 'Local turn, global correctness',
    narration: 'Each local left-turn or nonleft-turn test gives enough geometric evidence to push a new hull vertex or delete an interior point.',
    state: { turnCase: 'Left turn: point joins hull', stackUpdate: 'done' }
  }
];

function clearHighlights() {
  highlights.clear();
  Object.keys(pointRefs).forEach(function (k) { pointRefs[k].opacity(1); });
}
function ring(p, color) {
  return highlights.circle(18).center(p[0], p[1]).fill('none')
    .stroke({ color: color, width: 3, opacity: 0.95 });
}
function highLine(a, b, color, width, dash) {
  var l = line(highlights, a, b, color, width || 5, dash);
  l.opacity(0).animate(180).opacity(1);
  return l;
}
function highPoly(arr, color, opacity) {
  var p = polygon(highlights, arr, color, 0, color, 2);
  p.animate(180).fill({ color: color, opacity: opacity });
  return p;
}

function renderHighlights() {
  clearHighlights();

  if (stepState === 'start') return;

  if (stepState === 'testCandidate') {
    if (currentCase === 'left') {
      highPoly([A.p0, A.pi, A.pj], COLORS.amber, 0.22);
      highLine(A.p0, A.pj, COLORS.amber, 4);
      ring(A.pi, COLORS.amber);
      ring(A.pj, COLORS.amber);
      ring(A.p0, COLORS.amber);
    } else {
      highPoly([B.pi, B.pr, B.p0], COLORS.amber, 0.24);
      highLine(B.pi, B.pt, COLORS.amber, 3, '4,4');
      highLine(B.pr, B.pt, COLORS.amber, 3, '4,4');
      ring(B.pt, COLORS.amber);
      ring(B.pi, COLORS.amber);
      ring(B.pr, COLORS.amber);
      ring(B.p0, COLORS.amber);
    }
  }

  if (stepState === 'leftTurnPush') {
    highPoly([A.p0, A.pi, A.pj], COLORS.blue, 0.16);
    highLine(A.p0, A.pi, COLORS.blue, 5);
    highLine(A.pi, A.pj, COLORS.blue, 5);
    ring(A.pi, COLORS.blue);
    ring(A.p0, COLORS.blue);
    ring(A.pj, COLORS.blue);
  }

  if (stepState === 'nonleftTurnPop') {
    highPoly([B.pi, B.pr, B.p0], COLORS.red, 0.15);
    highLine(B.pi, B.pr, COLORS.red, 3);
    highLine(B.pr, B.p0, COLORS.red, 3);
    highLine(B.p0, B.pi, COLORS.red, 3);
    ring(B.pt, COLORS.red);
    if (pointRefs.B_pt) pointRefs.B_pt.opacity(0.32);
    line(highlights, [B.pt[0] - 9, B.pt[1] - 9], [B.pt[0] + 9, B.pt[1] + 9], COLORS.red, 3);
    line(highlights, [B.pt[0] - 9, B.pt[1] + 9], [B.pt[0] + 9, B.pt[1] - 9], COLORS.red, 3);
  }

  if (stepState === 'done') {
    if (currentCase === 'left') {
      highLine(A.p0, A.pi, COLORS.green, 5);
      highLine(A.pi, A.pj, COLORS.green, 5);
      ring(A.pi, COLORS.green);
    } else {
      highLine(B.pi, B.pr, COLORS.green, 4);
      highLine(B.pr, B.p0, COLORS.green, 4);
      ring(B.pt, COLORS.red);
    }
  }
}

function setTurnCase(nonleft) {
  currentCase = nonleft ? 'nonleft' : 'left';
  var txt = nonleft ? 'Nonleft turn: point is interior' : 'Left turn: point joins hull';
  document.getElementById('turnCaseInput').checked = nonleft;
  document.getElementById('turnCaseVal').textContent = txt;
}

function setStackState(s) {
  stepState = s;
  document.getElementById('stackUpdateVal').textContent = s;
  renderHighlights();
}

function toggle_turnCase(on) {
  setTurnCase(on);
  if (on && stepState === 'leftTurnPush') {
    setStackState('testCandidate');
  } else if (!on && stepState === 'nonleftTurnPop') {
    setStackState('testCandidate');
  } else {
    renderHighlights();
  }
}

function trigger_stackUpdate() {
  var i = stackStates.indexOf(stepState);
  i = (i + 1) % stackStates.length;
  var next = stackStates[i];
  if (next === 'leftTurnPush' && currentCase === 'nonleft') next = 'nonleftTurnPop';
  if (next === 'nonleftTurnPop' && currentCase === 'left') next = 'done';
  setStackState(next);
  demoIndex = -1;
  document.getElementById('demoNarration').textContent =
    currentCase === 'left'
      ? 'Left turns keep the candidate on the outside boundary; the stack can push the candidate.'
      : 'Nonleft turns identify an interior middle point; the stack pops that point and retests.';
  document.getElementById('stepLabel').textContent = 'manual — ' + next;
}

function applyDemoStep(i) {
  demoIndex = (i + demoSteps.length) % demoSteps.length;
  var step = demoSteps[demoIndex];
  var nonleft = step.state.turnCase === 'Nonleft turn: point is interior';
  setTurnCase(nonleft);
  setStackState(step.state.stackUpdate);
  document.getElementById('demoNarration').textContent = step.narration;
  document.getElementById('stepLabel').textContent = (demoIndex + 1) + '/' + demoSteps.length + ' — ' + step.title;
}

function nextStep() {
  applyDemoStep(demoIndex + 1);
}

function prevStep() {
  if (demoIndex < 0) applyDemoStep(demoSteps.length - 1);
  else applyDemoStep(demoIndex - 1);
}

/* Keep the initial view a faithful black-and-gray reproduction: no colored highlights until interaction. */
setTurnCase(false);
setStackState('start');
window.__markRendered();
